// ── Helper ───────────────────────────────────────────────────────────────────

export function getTemplateForTopic(topic) {
  const key = topic
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '');
  return TOPIC_TEMPLATES[key] || null;
}

export function getAllTopicKeys() {
  return Object.keys(TOPIC_TEMPLATES);
}
